 if($('territoryMeter').dataset.key!==meterKey){$('territoryMeter').dataset.key=meterKey;const pieces=all.map(({f,stats:a})=>({name:f.name,land:a.land,color:palette(f.id).color}));if(neutralLand)pieces.push({name:'中立',land:neutralLand,color:neutral.color});$('territoryMeter').replaceChildren(...pieces.map(p=>{const n=document.createElement('span');n.style.width=(p.land/total*100)+'%';n.style.background=p.color;n.title=`${p.name} ${p.land} 格`;return n;}));$('territoryMeter').setAttribute('aria-label',pieces.map(p=>`${p.name} ${p.land} 格`).join('，'));}
