function updateUpgrades(){for(const key of Object.keys(E.UPGRADES)){const spec=E.UPGRADES[key],button=$('upgrade-'+key),level=state.upgrades[0][key],cost=E.upgradeCost(state,key);button.disabled=state.phase!=='playing'||!!aim||cost===null||state.gold[0]<cost;button.classList.toggle('maxed',cost===null);button.querySelector('.upgrade-level').textContent=level+'/'+spec.max;button.querySelector('.upgrade-cost').textContent=cost===null?'已满级':state.gold[0]<cost?`还差 ${Math.ceil(cost-state.gold[0])} 金`:`◆ ${cost} 升级`;button.setAttribute('aria-label',`${spec.name}，${level}/${spec.max} 级，${spec.description}，${cost===null?'已满级':cost+' 金币'}`);}}
