 const choices=state.phase==='playing'?E.available(state,0):[],key=choices.map(c=>`${c.id}:${c.id===selected}:${state.gold[0]>=E.TYPES[c.offer].cost}`).join('|')+'|'+!!aim;if($('quickBuilds').dataset.key!==key){$('quickBuilds').dataset.key=key;$('quickBuilds').replaceChildren(...choices.map(c=>{const b=document.createElement('button');b.textContent=`${icons[c.offer]} ${E.TYPES[c.offer].name} ${E.TYPES[c.offer].cost}`;b.disabled=!!aim;b.setAttribute('aria-label',`选择第 ${c.r+1} 排第 ${c.c+1} 列的${E.TYPES[c.offer].name}，${E.TYPES[c.offer].cost} 金币`);b.setAttribute('aria-pressed',String(c.id===selected));b.classList.toggle('selected',c.id===selected);b.addEventListener('click',()=>select(c.id));return b;}));if(!choices.length&&state.phase==='playing'){const note=document.createElement('span');note.className='empty-builds';note.textContent='暂无相连空地，等部队占领后继续扩建';$('quickBuilds').append(note);}}
