function updateRoutes(){if(!E.ROUTES)return;const route=state.routes[0],cost=E.routeCost(state,0);$('routeSummary').textContent=route.key?`${E.ROUTES[route.key].name} · ${route.level}/2 级`:'经济 / 防御 / 进攻，三选一';for(const [key,spec]of Object.entries(E.ROUTES)){const b=$('route-'+key),locked=!!route.key&&route.key!==key;b.disabled=state.phase!=='playing'||!!aim||locked||cost===null;b.classList.toggle('selected',route.key===key);b.classList.toggle('locked',locked);b.querySelector('.detail-cost').textContent=locked?'本局已锁定其他路线':cost===null?'2/2 级 · 已满级':state.gold[0]<cost?`◆ ${cost} · 还差 ${Math.ceil(cost-state.gold[0])} 金`:route.key?`◆ ${cost} · 预览 2 级`:`◆ ${cost} · 预览路线`;}}
function upgradeSelectedBuilding(branch){if(aim||selected===null)return;const result=E.upgradeBuilding(state,selected,branch,0);if(!result.ok){toast(result.reason);return;}toast(`${E.BUILDING_UPGRADES[state.cells[selected].building.type][branch].name} · 升至 ${result.level} 级`);beep(740,.12);updateUI();draw();}
function chooseRoute(key){if(aim)return;const result=state.routes[0].key?E.upgradeRoute(state,0):E.chooseRoute(state,key,0);if(!result.ok){toast(result.reason);return;}toast(`${E.ROUTES[key].name} · ${state.routes[0].level} 级`);beep(680,.12);updateUI();}
function clearDecision(){decision=null;$('decisionPanel').classList.add('hidden');$('commandPanel').classList.remove('has-decision');$('confirmDecision').disabled=true;}
function decisionValid(){if(!decision||state.phase!=='playing'||aim)return false;if(decision.kind==='route'){const route=state.routes[0];return route.key===decision.routeKey&&route.level===decision.level;}const c=state.cells[decision.source];return selected===decision.source&&c?.owner===0&&c.building===decision.building&&c.building.side===0&&c.building.level===decision.level&&c.building.hp>0;}
function previewDecision(kind,key){if(state.phase!=='playing'||aim)return;clearDecision();if(kind==='branch'){const c=state.cells[selected];if(!c?.building||c.building.side!==0)return;decision={kind,key,source:c.id,building:c.building,level:c.building.level};}else{decision={kind,key,routeKey:state.routes[0].key,level:state.routes[0].level};}updateDecision();syncContext();ensureVisible(selected);}
function updateDecision(){if(!decision)return;if(!decisionValid()){clearDecision();return;}const spec=decision.kind==='route'?E.ROUTES[decision.key]:E.BUILDING_UPGRADES[decision.building.type][decision.key],cost=decision.kind==='route'?E.routeCost(state,0):E.buildingUpgradeCost(state,decision.source,decision.key,0);if(cost===null){clearDecision();return;}const first=decision.kind==='route'?!decision.routeKey:!decision.building.branch;$('decisionPanel').classList.remove('hidden');$('commandPanel').classList.add('has-decision');$('decisionTitle').textContent=spec.name+' · '+(decision.kind==='route'?'路线':'建筑分支');$('decisionDescription').textContent=spec.description+(first?' 确认后锁定，其他'+(decision.kind==='route'?'路线':'分支')+'将不可选。':'')+(decision.kind==='branch'?' 本次另加基础耐久的 25%。':'');$('decisionCost').textContent=`◆ ${cost} · 升至 ${decision.level+1} 级`+(state.gold[0]<cost?` · 还差 ${Math.ceil(cost-state.gold[0])} 金`:'');$('confirmDecision').textContent=first?'确认选择':'确认升级';$('confirmDecision').disabled=state.gold[0]<cost;}
function confirmDecision(){if(!decisionValid()){clearDecision();return;}const choice=decision;clearDecision();if(choice.kind==='route')chooseRoute(choice.key);else upgradeSelectedBuilding(choice.key);layoutBoard();}
function setPanel(key){if(aim)return;if(activePanel!==key)clearDecision();activePanel=key;for(const tab of ['manage','route','tech']){$('tab-'+tab).classList.toggle('active',tab===key);$('tab-'+tab).setAttribute('aria-selected',String(tab===key));$('panel-'+tab).classList.toggle('hidden',tab!==key);}if(key!=='manage'){kingdomOpen=true;contextOpen=true;zoomed=false;}syncContext();applyCamera();}

function clearAim(){aim=null;$('aimDetails').open=false;$('commandPanel').classList.remove('is-aiming');$('aimPanel').classList.add('hidden');$('aimRibbon').classList.add('hidden');$('battlefield').classList.remove('is-aiming');$('confirmFire').disabled=true;}
function validAim(){if(!aim)return false;const c=state.cells[aim.source];return state.phase==='playing'&&c?.owner===0&&c.building===aim.building&&c.building.side===0&&c.building.type==='arsenal'&&c.building.hp>0;}
function beginAim(key){const c=selected!==null?state.cells[selected]:null;if(state.phase!=='playing'||!c||c.owner!==0||c.building?.side!==0||c.building.type!=='arsenal')return;clearDecision();resetGesture();setPanel('manage');contextOpen=true;kingdomOpen=false;aim={source:c.id,building:c.building,weapon:key,target:null,preview:null};updateUI();draw();ensureVisible(selected);canvas.focus({preventScroll:true});}
function selectAimTarget(id){if(!validAim()){clearAim();updateUI();return;}aim.target=id;updateUI();ensureVisible(id);draw();}
function updateAim(){if(!aim)return;if(!validAim()){clearAim();toast('瞄准已取消：军械库不可用');return;}const spec=E.WEAPONS[aim.weapon],status=E.weaponStatus(state,aim.source,aim.weapon,0);aim.preview=aim.target===null?null:E.previewWeapon(state,aim.source,aim.weapon,aim.target,0);$('aimPanel').classList.remove('hidden');$('commandPanel').classList.add('is-aiming');$('aimRibbon').classList.remove('hidden');$('battlefield').classList.add('is-aiming');$('aimTitle').textContent=`⌖ ${spec.name} · ${aim.target===null?'请选择目标':'第 '+(state.cells[aim.target].r+1)+' 排 / '+(state.cells[aim.target].c+1)+' 列'}`;
 const currentDamage=aim.preview||E.previewWeapon(state,aim.source,aim.weapon,aim.source,0),ready=aim.preview?.ok;
 $('aimDescription').textContent=`${status.cost}金 / ${status.ammoCost}弹 · 库存 ${status.ammo}/${status.maxAmmo} · 射程 ${status.range}格\n`+(aim.target===null?'点地图选目标 · 不伤友军':ready?'目标在射程内 · 点击开火':'不可开火：'+aim.preview.reason);
 $('aimDamage').textContent=`本次伤害：部队 ${displayNumber(currentDamage.damage)} / 建筑 ${displayNumber(currentDamage.buildingDamage)}`+(aim.weapon==='rail'?' · 沿方向穿透至射程终点':' · 爆炸半径 '+currentDamage.radius+' 格');$('confirmFire').disabled=!ready;$('confirmFire').textContent=`开火 · ${status.cost}金`;$('confirmFire').setAttribute('aria-label',ready?`确认向第${state.cells[aim.target].r+1}排第${state.cells[aim.target].c+1}列开火，消耗${status.cost}金币和${status.ammoCost}发弹药，不伤友军`:'请先选择有效目标');}

function confirmFire(){if(!validAim()){clearAim();updateUI();return;}if(aim.target===null)return;const shot={...aim},preview=E.previewWeapon(state,shot.source,shot.weapon,shot.target,0),result=E.fireWeapon(state,shot.source,shot.weapon,shot.target,0);if(!result.ok){toast(result.reason);updateUI();return;}weaponEffects.push({kind:shot.weapon,source:shot.source,target:shot.target,cells:preview.cells||[],line:preview.line,radius:preview.radius,birth:performance.now()});const p=point(state.cells[shot.target]);particles.push({x:p.x,y:p.y-20,text:shot.weapon==='rail'?'穿透发射！':'重炮轰击！',color:'#fff1a5',birth:performance.now()});closeContext(false);toast(`${E.WEAPONS[shot.weapon].name}已发射 · 友军安全`);beep(shot.weapon==='rail'?180:110,.25);updateUI();draw();}
function drawAim(){if(!aim||!validAim())return;const source=point(state.cells[aim.source]),status=E.weaponStatus(state,aim.source,aim.weapon,0);ctx.save();ctx.beginPath();ctx.arc(source.x,source.y,status.range*S,0,Math.PI*2);ctx.strokeStyle='#fff2bb90';ctx.lineWidth=1.5;ctx.setLineDash([5,5]);ctx.stroke();ctx.setLineDash([]);ellipse(source.x,source.y,7,7,'#fff2a9cc');if(aim.preview){for(const id of aim.preview.cells||[]){const c=state.cells[id];if(!c)continue;const p=point(c);poly(p.x,p.y,R-2);ctx.fillStyle=aim.preview.ok?'#ff8a474f':'#e1c79935';ctx.fill();ctx.strokeStyle=aim.preview.ok?'#fff1ae':'#e4ba98';ctx.lineWidth=1.5;ctx.stroke();}if(aim.preview.line){const l=aim.preview.line;line(OX+l.from.x*S,OY+l.from.y*S,OX+l.to.x*S,OY+l.to.y*S,'#ffecae99',Math.max(2,l.width*S*2));line(OX+l.from.x*S,OY+l.from.y*S,OX+l.to.x*S,OY+l.to.y*S,'#fff5d7',2);}if(aim.target!==null){const t=point(state.cells[aim.target]);if(aim.preview.radius){ctx.beginPath();ctx.arc(t.x,t.y,aim.preview.radius*S,0,Math.PI*2);ctx.strokeStyle='#ffe6a5bb';ctx.lineWidth=2;ctx.setLineDash([5,3]);ctx.stroke();ctx.setLineDash([]);}ctx.beginPath();ctx.arc(t.x,t.y,15,0,Math.PI*2);ctx.strokeStyle='#fffbe0';ctx.lineWidth=2;ctx.stroke();line(t.x-22,t.y,t.x-9,t.y,'#fffbe0',2);line(t.x+9,t.y,t.x+22,t.y,'#fffbe0',2);line(t.x,t.y-22,t.x,t.y-9,'#fffbe0',2);line(t.x,t.y+9,t.x,t.y+22,'#fffbe0',2);}}ctx.restore();}
function drawWeaponEffects(){const now=performance.now();weaponEffects=weaponEffects.filter(f=>now-f.birth<1100);for(const effect of weaponEffects){const t=(now-effect.birth)/1100,source=point(state.cells[effect.source]),target=point(state.cells[effect.target]);ctx.save();ctx.globalAlpha=1-t;if(effect.kind==='rail'&&effect.line){const l=effect.line;line(OX+l.from.x*S,OY+l.from.y*S,OX+l.to.x*S,OY+l.to.y*S,'#ffad4b',18*(1-t)+2);line(OX+l.from.x*S,OY+l.from.y*S,OX+l.to.x*S,OY+l.to.y*S,'#fff9d7',5*(1-t)+1);}else{line(source.x,source.y,target.x,target.y,'#f5de9b88',2);ctx.beginPath();ctx.arc(target.x,target.y,8+t*R*2.5,0,Math.PI*2);ctx.fillStyle='#ffb94666';ctx.fill();ctx.strokeStyle='#fff0ab';ctx.lineWidth=6*(1-t)+1;ctx.stroke();}for(const id of effect.cells){const p=point(state.cells[id]);ellipse(p.x+Math.sin(id)*t*15,p.y-t*24,3*(1-t)+1,3*(1-t)+1,'#fff4ba');}ctx.restore();}}
