function hitCell(e){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height||e.clientX<rect.left||e.clientY<rect.top||e.clientX>rect.left+rect.width||e.clientY>rect.top+rect.height)return null;const {w,h}=viewMetrics(),x=((e.clientX-rect.left)/rect.width*w-w/2)/camera.scale+camera.x,y=((e.clientY-rect.top)/rect.height*h-h/2)/camera.scale+camera.y;let nearest=null,dist=Infinity;for(const c of state.cells){const p=point(c),d=Math.hypot(x-p.x,y-p.y);if(d<dist){dist=d;nearest=c;}}return nearest&&dist<=R?nearest:null;}
